57	    /** Each base task has a depth in the pedigree tree, the value of
58	    the next magic number, a unique gamma value that is the dot
59	    product of the task's pedigree and the magic numbers array, and a
60	    dot product that is the task's gamma value with extra magic added
61	    in for each random number the task generates **/
62	
63	    private int depth;
64	    private long nextMagicNumber; 
65	    private long gamma; 
66	    private long dotProduct;
67	    
68	    // The constructor used by the primordial task.
69	    public BaseTask() {
70	        super();
71	        this.parent = null;
72	        this.transaction = null;
73	
74	        // Pedigree information
75	        this.depth = 0;
76	        this.nextMagicNumber = 
77	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
78	        this.gamma = 
79	            MagicNumbers.trulyRandomLongNumbers(this.depth);
80	        this.dotProduct = this.gamma;
81	    }
82	
83	    public BaseTask(BaseTask parent) {
84	        super();
85	        this.parent = parent;
86	        this.transaction = parent.transaction;
87	
88	        // Pedigree information
89	        this.depth = parent.getDepth() + 1;
90	        this.nextMagicNumber = 
91	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
92	        this.gamma = parent.makeNewChild();
93	        this.dotProduct = this.gamma;
94	    }
95	
96	    private int getDepth() {
97	        return this.depth;
98	    }
99	
100	    /* Returns a unique gamma for a child task */
101	    public long makeNewChild() {
102	        this.gamma += this.nextMagicNumber;
103	        return this.gamma;
104	    }
105	
106	    /* Records that a new random number has been asked for, and
107	     * returns the task's dotProduct */
108	    public long makeNewRandom() {
109	        this.dotProduct += this.nextMagicNumber;
110	        return dotProduct;
111	    }
