113	    /* For a group of arms that completes abruptly: waits for this arm
114	     * where it was forked, and takes what it threw.  An arm that was never
115	     * forked is not run.  The current task is saved and restored around the
116	     * join, as joinOrRun does. */
117	    public final void joinIfForked() {
118	        if (actuallyForked == UNFORKED) return;
119	        Thread thread = Thread.currentThread();
120	        if (thread instanceof FortressTaskRunner) {
121	            FortressTaskRunner ftr = (FortressTaskRunner) thread;
122	            BaseTask saved = ftr.task();
123	            try {
124	                this.quietlyJoin();
125	            } finally {
126	                ftr.setTask(saved);
127	            }
128	        } else {
129	            this.quietlyJoin();
130	        }
131	    }
