142	    // Corner case: we attempted to spawn work from a class
143	    // initializer.  That doesn't work as the initializer isn't run in
144	    // a ForkJoinWorkerThread.  So we must submit the task to the
145	    // global task pool instead.
146	    private final void executeAlways() {
147	        FortressExecutable.group.execute(this);
148	        actuallyForked = EXECUTED;
149	    }
