156	    public final void forkIfProfitable() {
157	        if (ForkJoinTask.inForkJoinPool()) {
158	            if (unsafeWorthSpawning()) {
159	                this.forkAlways();
160	            }
161	        } else {
162	            this.executeAlways();
163	        }
164	    }
