166	    public final void joinOrRun() {
167	        // Emphasize common UNFORKED case.
168	        if (actuallyForked == UNFORKED) {
169	            this.compute();
170	        } else {
171	            // java.util.concurrent has no helpJoin(); its join() already
172	            // helps by running queued subtasks when called from a worker
173	            // thread, so FORTRESS_HELP_JOIN (useHelpJoin) is now a no-op.
174	            //
175	            // That helping breaks an invariant jsr166y's blocking join
176	            // preserved: generated compute() bodies point the worker's
177	            // current-task field at themselves (BaseTask.setTask) and never
178	            // restore it, and the transaction statics below resolve the
179	            // current transaction through that field.  A task run on this
180	            // thread while join() helps leaves the field pointing at an
181	            // unrelated task, corrupting transaction state in the joiner's
182	            // continuation.  Save and restore the field across join(),
183	            // mirroring Evaluator's setCurrentTask(currentTask) after
184	            // TupleTask.invokeAll on the interpreter side.
185	            Thread thread = Thread.currentThread();
186	            if (thread instanceof FortressTaskRunner) {
187	                FortressTaskRunner ftr = (FortressTaskRunner) thread;
188	                BaseTask saved = ftr.task();
189	                try {
190	                    this.join();
191	                } finally {
192	                    ftr.setTask(saved);
193	                }
194	            } else {
195	                this.join();
196	            }
197	        }
198	    }
