210	    public static void endTransaction() {
211	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
212	        BaseTask currentTask = ftr.getTask();
213	        if (debug) debug("endTransaction: ftr = " + ftr + " current task = " + currentTask);
214	        Transaction transaction = ftr.getTask().transaction();
215	        if (debug) debug("End transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
216	        if (transaction != null) {
217	            transaction.TXCommit();
218	            currentTask.setTransaction(transaction.getParent());
219	        }
