234	    public static void delayTransaction() {
235	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
236	        long startTime = System.nanoTime();
237	        long elapsedTime = System.nanoTime() - startTime;
238	
239	        if (useExponentialBackoff) {
240	            double r = gen.nextDouble() + 0.5; // Random number between 0.5 and 1.5
241	            long waitNanoseconds = (long) ((1L << (ftr.getRetries() + machineConstant)) * r);
242	            
243	            while (elapsedTime < waitNanoseconds) {
244	                elapsedTime = System.nanoTime() - startTime;
245	            }
246	        }
247	        
248	        ftr.incElapsedTime(elapsedTime);
249	        ftr.incRetries();
250	    }
